308: export function encodeTask(task) { return JSON.stringify(task, null, 2) + '\n'; }
309: export function restoreTask(serialized, registry, inventory) {
310:   const task = JSON.parse(serialized);
311:   assert(task.schema_version === 1 && task.id && task.goal && Array.isArray(task.acceptance) && task.acceptance.length, 'Invalid Task Context');
312:   assert(Boolean(task.workflow_id) !== Boolean(task.skill_id), 'Choose one registered workflow or one existing Skill');
313:   assert(task.acceptance.every(item => typeof item === 'string' && item.length)
314:     && new Set(task.acceptance).size === task.acceptance.length, 'Invalid acceptance IDs');
315:   for (const name of ['decisions', 'risks', 'permission_refs', 'evidence', 'changes', 'unresolved', 'history', 'next_actions']) assert(Array.isArray(task[name]), `Invalid ${name}`);
316:   assert(task.scope && Array.isArray(task.scope.files) && Array.isArray(task.scope.modules) && Array.isArray(task.scope.interfaces), 'Invalid scope');
317:   const workflow = definition(task, registry, inventory);
318:   assert(task.steps && Object.keys(task.steps).length === workflow.stages.length, 'Invalid step set');
319:   for (const stage of workflow.stages) {
320:     const step = task.steps[stage.id];
321:     assert(step && states.has(step.status) && Number.isInteger(step.attempts) && step.attempts >= 0 && Array.isArray(step.evidence_ids), 'Invalid step state');
322:     if (step.status === 'running') step.status = 'interrupted';
323:   }
324:   assert(new Set(task.evidence.map(e => e.id)).size === task.evidence.length, 'Duplicate evidence IDs');
325:   // No grants, trustedEvidence, capabilities, conditions or runtime commands restored.
326:   task.next_actions = [];
327:   return task;
328: }
