1: /** Platform-neutral serial coordination. No command execution, network or persistence.
2:  * Registry and host attestations are trusted inputs, never imported from Task Context.
3:  */
4: import { createHash } from 'node:crypto';
5: import { lstatSync, readFileSync, readdirSync, realpathSync } from 'node:fs';
6: import path from 'node:path';
7: 
8: export const digest = value => createHash('sha256').update(JSON.stringify(value)).digest('hex');
9: export const taskBinding = task => digest({ id: task.id, goal: task.goal, acceptance: task.acceptance, decisions: task.decisions });
10: const copy = value => JSON.parse(JSON.stringify(value));
11: const assert = (ok, message) => { if (!ok) throw new Error(message); };
12: const states = new Set(['pending', 'running', 'completed', 'reused', 'skipped', 'evidence_insufficient', 'permission_blocked', 'validation_failed', 'interrupted']);
13: const allowedCapabilities = ['read_files', 'write_files', 'run_shell_commands', 'access_network', 'destructive_actions_allowed'];
14: const safePath = p => typeof p === 'string' && p !== '' && !path.isAbsolute(p) && !p.split(/[\\/]/).includes('..');
15: 
16: function checkPath(root, relative) {
17:   assert(safePath(relative), 'Dependency path must be repository-relative');
18:   let current = realpathSync(root);
19:   for (const part of relative.split(/[\\/]/)) {
20:     current = path.join(current, part);
21:     try { assert(!lstatSync(current).isSymbolicLink(), 'Symlink paths require host inspection'); }
22:     catch (error) { if (error.code !== 'ENOENT') throw error; }
23:   }
24:   return current;
25: }
26: 
27: // Include directory membership (new/deleted files), executable bits and file bytes.
28: // Never follow symlinks or read outside the explicitly supplied repository root.
29: export function fingerprint(root, relative) {
30:   const current = checkPath(root, relative);
31:   try { lstatSync(current); } catch (error) { if (error.code === 'ENOENT') return 'missing'; throw error; }
32:   function visit(file) {
33:     const stat = lstatSync(file);
34:     assert(!stat.isSymbolicLink(), 'Symlink dependencies require host inspection');
35:     if (stat.isDirectory()) return readdirSync(file).sort().map(name => [name, visit(path.join(file, name))]);
36:     assert(stat.isFile(), 'Only regular files/directories can be fingerprinted');
37:     return [stat.mode & 0o111, createHash('sha256').update(readFileSync(file)).digest('hex')];
38:   }
39:   return digest(visit(current));
40: }
41: 
42: export function captureEvidence(root, input, environment) {
43:   assert(input.id && input.source && input.summary, 'Evidence needs id, source and summary');
44:   assert(Array.isArray(input.dependencies) && input.dependencies.length, 'Evidence needs dependency coverage');
45:   const bindings = Object.fromEntries(input.dependencies.map(p => [p, fingerprint(root, p)]));
46:   return { ...copy(input), bindings, environment: copy(environment), recorded_at: new Date().toISOString() };
47: }
48: 
49: export function evidenceValidity(evidence, host) {
50:   if (!evidence || !host.trustedEvidence?.has(digest(evidence))) return { status: 'unknown', reason: 'source_not_attested' };
51:   if (evidence.result !== 'pass') return { status: 'failed', reason: 'observed_failure' };
52:   if (!evidence.coverage_complete || !evidence.bindings || !Object.keys(evidence.bindings).length
53:       || !evidence.environment || !Object.keys(evidence.environment).length) {
54:     return { status: 'unknown', reason: 'dependency_or_environment_coverage_unknown' };
55:   }
56:   if (evidence.kind === 'test' && (!evidence.command || !evidence.cwd || evidence.exit_code !== 0)) {
57:     return { status: 'unknown', reason: 'execution_receipt_missing' };
58:   }
59:   if (evidence.kind === 'signal' && (!evidence.command || !evidence.cwd || !Number.isInteger(evidence.exit_code)
60:       || !evidence.observed_target_failure || !evidence.success_criterion || !evidence.failure_criterion)) {
61:     return { status: 'unknown', reason: 'reliable_failure_signal_missing' };
62:   }
63:   for (const [key, value] of Object.entries(evidence.environment)) {
64:     if (!(key in (host.environment ?? {}))) return { status: 'unknown', reason: `environment_unknown:${key}` };
65:     if (host.environment[key] !== value) return { status: 'stale', reason: `environment_changed:${key}` };
66:   }
67:   try {
68:     for (const [file, hash] of Object.entries(evidence.bindings)) {
69:       if (fingerprint(host.root, file) !== hash) return { status: 'stale', reason: `dependency_changed:${file}` };
70:     }
71:   } catch (error) { return { status: 'unknown', reason: error.message }; }
72:   return { status: 'valid', reason: 'attested_inputs_unchanged' };
73: }
74: 
75: export function validationPlan(evidence, host) {
76:   return evidence.map(item => ({ id: item.id, ...evidenceValidity(item, host) }))
77:     .map(item => ({ ...item, action: item.status === 'valid' ? 'reuse' : item.status === 'unknown' ? 'investigate' : 'rerun' }));
78: }
79: 
80: export function reviewBinding(root, task, baseline, files) {
81:   assert(baseline && Array.isArray(files) && files.length, 'Review needs a baseline and complete changed/related paths');
82:   return digest({ baseline, goal: task.goal, acceptance: task.acceptance, decisions: task.decisions,
83:     files: [...new Set(files)].sort().map(file => [file, fingerprint(root, file)]) });
84: }
85: 
86: function definition(task, registry, inventory) {
87:   assert(task.registry_binding === digest(registry), 'Registry changed; explicitly migrate/reselect workflow');
88:   if (task.workflow_id) {
89:     const workflow = registry.workflows[task.workflow_id];
90:     assert(workflow, 'Unknown registered workflow');
91:     return workflow;
92:   }
93:   assert(inventory.has(task.skill_id), 'Unknown single Skill');
94:   return { stages: [{ id: 'task', type: 'skill', skill: task.skill_id, optional: false, condition: 'always', prerequisites: [], next: [], permission: inventory.get(task.skill_id).permissions.write_files ? 'write_scoped' : 'read_only', stop_conditions: [] }], stop_conditions: [] };
95: }
96: 
97: export function createTask({ id, goal, acceptance, workflow_id = null, skill_id = null }, registry, inventory) {
98:   assert(id && goal && Array.isArray(acceptance) && acceptance.length, 'Goal and acceptance are required');
99:   assert(acceptance.every(item => typeof item === 'string' && item.length) && new Set(acceptance).size === acceptance.length, 'Acceptance IDs must be distinct strings');
100:   assert(Boolean(workflow_id) !== Boolean(skill_id), 'Choose one registered workflow or one existing Skill');
101:   const task = { schema_version: 1, id, goal, acceptance: copy(acceptance), workflow_id, skill_id,
102:     registry_binding: digest(registry), decisions: [], scope: { files: [], modules: [], interfaces: [] },
103:     risks: [], permission_refs: [], evidence: [], changes: [], unresolved: [], next_actions: [],
104:     current_stage: null, steps: {}, history: [] };
105:   for (const stage of definition(task, registry, inventory).stages) task.steps[stage.id] = { status: 'pending', attempts: 0, evidence_ids: [] };
106:   return task;
107: }
108: 
109: function evidenceFor(task, ids, host) {
110:   return ids?.length > 0 && ids.every(id => {
111:     const evidence = task.evidence.find(e => e.id === id);
112:     return evidence?.task_binding === taskBinding(task) && evidenceValidity(evidence, host).status === 'valid';
113:   });
114: }
115: function condition(task, name, host) {
116:   if (name === 'always') return true;
117:   const fact = host.conditions?.[name];
118:   return fact && typeof fact.value === 'boolean' && fact.reason && evidenceFor(task, fact.evidence_ids, host) ? fact.value : undefined;
119: }
120: function permission(skill, stage, task, host) {
121:   const metadata = host.inventory.get(skill);
122:   if (!metadata || !['draft', 'beta', 'stable'].includes(metadata.status)) return 'skill_unavailable';
123:   const request = host.requests?.[stage.id];
124:   if (!request) return 'operation_scope_missing';
125:   if (!Array.isArray(request.capabilities) || !request.capabilities.length) return 'capabilities_missing';
126:   if (stage.permission === 'write_scoped' && !request.capabilities.includes('write_files')) return 'write_scope_missing';
127:   if (stage.permission === 'read_only' && request.capabilities.includes('write_files')) return 'read_only_stage';
128:   for (const capability of request.capabilities) {
129:     if (!allowedCapabilities.includes(capability) || metadata.permissions?.[capability] !== true
130:         || host.capabilities?.[capability] !== true) return `capability_denied:${capability}`;
131:     const grants = host.grants?.filter(g => g.task_id === task.id && g.capability === capability && g.source
132:       && g.skills.includes(skill)) ?? [];
133:     if (!grants.length) return `user_authorization_missing:${capability}`;
134:     if (['read_files', 'write_files'].includes(capability)) {
135:       if (!request.paths?.length || request.paths.some(p => !safePath(p))) return 'explicit_paths_missing';
136:       if (request.paths.some(p => !grants.some(g => g.paths?.includes(p)))) return `path_not_authorized:${capability}`;
137:       try { for (const p of request.paths) checkPath(host.root, p); } catch { return 'unsafe_path'; }
138:     } else if (!request.operation || !grants.some(g => g.operations?.includes(request.operation))) return `operation_not_authorized:${capability}`;
139:   }
140:   if (request.capabilities.includes('run_shell_commands') && request.preflight !== 'safe') return 'command_preflight_missing';
141:   return null;
142: }
143: 
144: function requirement(task, requirement, host) {
145:   return task.evidence.some(e => e.claims?.includes(requirement.claim)
146:     && e.task_binding === taskBinding(task)
147:     && (!requirement.skill || e.skill === requirement.skill)
148:     && (!requirement.kind || e.kind === requirement.kind)
149:     && (requirement.kind !== 'review' || (e.kind === 'review' && e.independent === true && host.reviewBinding && e.review_basis === host.reviewBinding))
150:     && evidenceValidity(e, host).status === 'valid');
151: }
152: 
153: function stepEvidence(task, stage, host) {
154:   const step = task.steps[stage.id];
155:   if (!evidenceFor(task, step.evidence_ids, host)) return false;
156:   const evidence = step.evidence_ids.map(id => task.evidence.find(e => e.id === id));
157:   if (!evidence.some(e => e.skill === stage.skill && e.claims?.includes(`stage:${stage.id}`))) return false;
158:   if (stage.skill === 'safe-code-review' && !evidence.some(e => e.kind === 'review' && e.independent === true
159:       && e.review_basis && e.review_basis === host.reviewBinding)) return false;
160:   if (stage.skill === 'bug-root-cause-analysis' && !evidence.some(e => e.signal_ids?.length
161:       && e.signal_ids.every(id => task.evidence.some(signal => signal.id === id && signal.kind === 'signal'
162:         && evidenceValidity(signal, host).status === 'valid')))) return false;
163:   return true;
164: }
165: 
166: /** Recompute a decision every time. No imported context field grants execution authority. */
167: export function nextAction(task, host) {
168:   assert(new Set(task.evidence.map(e => e.id)).size === task.evidence.length, 'Duplicate evidence IDs');
169:   const workflow = definition(task, host.registry, host.inventory);
170:   assert(Object.keys(task.steps).length === workflow.stages.length && workflow.stages.every(s => task.steps[s.id]), 'Task stages differ from Registry');
171:   if (!host.scopeReviewed) return { action: 'evidence_insufficient', reason: 'risk_and_dependency_scope_not_reviewed' };
172:   if (workflow.stages.length > 1 && !host.continuationAuthorized) return { action: 'permission_blocked', reason: 'continuous_workflow_not_authorized' };
173:   if (host.openDecisions?.length) return { action: 'decision_required', skill: 'requirements-clarification', reason: host.openDecisions.join(', ') };
174:   if (host.activeStops?.length) return { action: 'blocked', reason: host.activeStops.join(', ') };
175:   const completed = new Set();
176:   for (const stage of workflow.stages) {
177:     const step = task.steps[stage.id];
178:     if (stage.prerequisites.some(id => !completed.has(id))) continue;
179:     const applies = condition(task, stage.condition, host);
180:     const decision = { stage: stage.id, skill: stage.skill };
181:     const stop = [...(workflow.stop_conditions ?? []), ...stage.stop_conditions]
182:       .find(name => condition(task, name, host) === true);
183:     if (stop) return { ...decision, action: 'blocked', reason: `stop_condition:${stop}` };
184:     if (applies === undefined) return { ...decision, action: 'evidence_insufficient', reason: `condition_unknown:${stage.condition}` };
185:     if (!applies) {
186:       if (!stage.optional) return { ...decision, action: 'evidence_insufficient', reason: `required_condition_false:${stage.condition}` };
187:       if (step.status !== 'skipped' || step.condition_binding !== digest(host.conditions[stage.condition])) return { ...decision, action: 'skip', reason: `not_applicable:${stage.condition}` };
188:       completed.add(stage.id); continue;
189:     }
190:     if (stage.type === 'gate') {
191:       const children = workflow.stages.filter(s => s.approval_gate === stage.id);
192:       if (!children.length) return { ...decision, action: 'permission_blocked', reason: 'gate_has_no_consumer' };
193:       for (const child of children) {
194:         const denied = permission(child.skill, child, task, host);
195:         if (denied) return { ...decision, action: 'permission_blocked', reason: denied };
196:       }
197:       // Always re-evaluate gates against host grants, never reuse persisted approval.
198:       if (step.status !== 'completed') return { ...decision, action: 'approve', reason: 'existing_scoped_host_authorization' };
199:       completed.add(stage.id); continue;
200:     }
201:     if (['running', 'interrupted'].includes(step.status)) return { ...decision, action: 'blocked', reason: 'inflight_operation_needs_reconciliation' };
202:     if (['completed', 'reused'].includes(step.status) && stepEvidence(task, stage, host)) {
203:       completed.add(stage.id); continue;
204:     }
205:     const failure = step.status === 'validation_failed';
206:     if (failure) return { ...decision, action: 'validation_failed', reason: step.reason || 'explicit_retry_required' };
207:     const denied = permission(stage.skill, stage, task, host);
208:     if (denied) return { ...decision, action: 'permission_blocked', reason: denied };
209:     // Risk checks are additive obligations referencing existing Skills, not new workflows.
210:     if (stage.permission === 'write_scoped') {
211:       const gap = (host.risks ?? []).flatMap(r => host.registry.coordination?.risk_requirements?.[r]?.before_write ?? [{ claim: `unclassified-risk:${r}` }])
212:         .find(r => !requirement(task, r, host));
213:       if (gap) return { ...decision, action: 'risk_check', requirement: gap, reason: 'risk_requires_additional_evidence' };
214:     }
215:     const candidate = host.reuse?.[stage.id];
216:     if (candidate) {
217:       const provisional = copy(task); provisional.steps[stage.id].evidence_ids = candidate;
218:       if (stepEvidence(provisional, stage, host)) return { ...decision, action: 'reuse', evidence_ids: candidate, reason: 'valid_existing_result' };
219:     }
220:     if (stage.permission === 'write_scoped' && ['completed', 'reused'].includes(step.status)) {
221:       return { ...decision, action: 'blocked', reason: 'stale_write_result_needs_reconciliation' };
222:     }
223:     return { ...decision, action: 'execute', reason: ['completed', 'reused'].includes(step.status) ? 'prior_evidence_stale_or_unknown' : 'applicable_stage', mode: host.execution === 'same_agent' ? 'same_agent' : 'manual_handoff' };
224:   }
225:   if (completed.size !== workflow.stages.length) return { action: 'evidence_insufficient', reason: 'unresolved_dependencies' };
226:   const obligations = [
227:     ...task.acceptance.map(id => ({ claim: `acceptance:${id}` })),
228:     ...([...completed].some(id => {
229:       const stage = workflow.stages.find(s => s.id === id);
230:       return task.steps[id].status !== 'skipped'
231:         && ['feature-implementation', 'safe-fix-implementation', 'safe-test-implementation'].includes(stage.skill);
232:     }) ? [{ claim: 'behavior-validation', kind: 'test' }] : []),
233:     ...(host.deliveryRequirements ?? []),
234:     ...(host.risks ?? []).flatMap(r => {
235:       const rules = host.registry.coordination?.risk_requirements?.[r];
236:       return rules ? [...rules.before_write, ...rules.before_delivery] : [{ claim: `unclassified-risk:${r}` }];
237:     }),
238:   ];
239:   const missing = obligations.filter(r => !requirement(task, r, host));
240:   if (task.unresolved.length || missing.length) return { action: 'evidence_insufficient', reason: 'delivery_not_proven', missing };
241:   return { action: 'complete', reason: 'applicable_stages_and_acceptance_proven', release_authorized: false };
242: }
243: 
244: function event(task, stage, status, reason) {
245:   task.current_stage = stage;
246:   task.history.push({ sequence: task.history.length + 1, stage, status, reason });
247: }
248: 
249: export function advance(task, host) {
250:   const action = nextAction(task, host);
251:   if (['skip', 'approve', 'reuse', 'execute'].includes(action.action)) {
252:     const step = task.steps[action.stage];
253:     step.status = { skip: 'skipped', approve: 'completed', reuse: 'reused', execute: 'running' }[action.action];
254:     step.reason = action.reason;
255:     if (action.action === 'execute') {
256:       step.attempts++;
257:       step.request_binding = digest(host.requests[action.stage]);
258:     }
259:     if (action.action === 'skip') {
260:       const stage = definition(task, host.registry, host.inventory).stages.find(s => s.id === action.stage);
261:       step.condition_binding = digest(host.conditions[stage.condition]);
262:     }
263:     if (action.evidence_ids) step.evidence_ids = action.evidence_ids;
264:     event(task, action.stage, step.status, action.reason);
265:   }
266:   task.next_actions = [action];
267:   return action;
268: }
269: 
270: export function finishStep(task, stageId, evidenceIds, host, failureReason = null) {
271:   const stage = definition(task, host.registry, host.inventory).stages.find(s => s.id === stageId);
272:   const step = task.steps[stageId];
273:   assert(stage && step?.status === 'running', 'Only a running stage may finish');
274:   assert(step.request_binding === digest(host.requests[stageId]), 'Operation scope changed while running');
275:   const denied = permission(stage.skill, stage, task, host);
276:   assert(!denied, denied);
277:   if (failureReason) { step.status = 'validation_failed'; step.reason = failureReason; step.evidence_ids = [...evidenceIds]; }
278:   else {
279:     const provisional = copy(task); provisional.steps[stageId].evidence_ids = evidenceIds;
280:     assert(stepEvidence(provisional, stage, host), 'Completion requires valid, scoped evidence and independent review');
281:     step.evidence_ids = [...evidenceIds]; step.status = 'completed';
282:   }
283:   event(task, stageId, step.status, failureReason || 'observed_completion');
284: }
285: 
286: /** Reopening is an explicit host decision; only descendants are reopened.
287:  * Evidence is retained, so still-valid independent checks can be reused.
288:  */
289: export function reopen(task, stageId, host, { reason, source, safeToRetry = false } = {}) {
290:   assert(reason && source, 'Reopen requires a sourced reason');
291:   const workflow = definition(task, host.registry, host.inventory);
292:   assert(task.steps[stageId], 'Unknown stage');
293:   const affected = new Set([stageId]);
294:   let changed = true;
295:   while (changed) { changed = false; for (const stage of workflow.stages) {
296:     if (!affected.has(stage.id) && stage.prerequisites.some(id => affected.has(id))) { affected.add(stage.id); changed = true; }
297:   } }
298:   for (const id of affected) {
299:     const stage = workflow.stages.find(s => s.id === id);
300:     if (['running', 'interrupted'].includes(task.steps[id].status)
301:         || (stage.permission === 'write_scoped' && ['completed', 'reused'].includes(task.steps[id].status))) {
302:       assert(safeToRetry && host.reconciled?.has(id), 'Unknown side effects must be reconciled before retry');
303:     }
304:   }
305:   for (const id of affected) { task.steps[id].status = 'pending'; event(task, id, 'pending', `${reason} (${source})`); }
306: }
